-- Synthetic only: no provider calls; all credentials and messages roll back.
begin;
select no_plan();
create function pg_temp.ne_id(n integer) returns uuid language sql immutable as $$select ('af090000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table ne_ev(k text primary key,v jsonb);grant all on ne_ev to authenticated,service_role;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.ne_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','nonexpiring-'||n||'@test.invalid' from generate_series(1,3)n;
insert into public.profiles(id,role,name) select pg_temp.ne_id(n),case n when 2 then 'teacher' else 'admin' end,'Synthetic expiry fixture' from generate_series(1,3)n on conflict(id) do update set role=excluded.role;
update dashboard_private.ai_agent_chat_support set issuance_enabled=true;
update dashboard_private.chat_space_configuration set configured=true,resource_name='spaces/NE_'||space_key;
create function pg_temp.ne_input(n integer,spaces text[] default array['space_1','space_2','space_3','space_4','space_5','space_6','space_7']) returns jsonb language sql as $$select jsonb_build_object('label','Synthetic indefinite reply','scopes',array['chat:outbox:read','chat:send'],'grant',jsonb_build_object('spaceKeys',spaces,'purposes',array['bridge_reply'],'bridgeSourceId',pg_temp.ne_id(90)),'expiresAt',null,'nonExpiring',true,'idempotencyKey',pg_temp.ne_id(n))$$;
create function pg_temp.ne_issue(i jsonb) returns jsonb language sql as $$select public.ai_agent_credential_api_v1('create',i)$$;
create function pg_temp.ne_hash(k text default 'all') returns text language sql as $$select encode(sha256(convert_to(v->>'token','UTF8')),'hex') from ne_ev where ne_ev.k=ne_hash.k$$;
create function pg_temp.ne_chat(action text,i jsonb,k text default 'all') returns jsonb language sql as $$select public.ai_agent_chat_api_v1(pg_temp.ne_hash(k),action,i)$$;
create function pg_temp.ne_message(n integer,space text) returns jsonb language sql as $$select jsonb_build_object('idempotencyKey',pg_temp.ne_id(1000+n),'clientMessageId',pg_temp.ne_id(2000+n),'bridgeSourceId',pg_temp.ne_id(90),'sourceEventId','spaces/NE_'||space||'/messages/synthetic-'||n,'spaceKey',space,'threadName','spaces/NE_'||space||'/threads/existing','text','Synthetic reply')$$;
select set_config('request.jwt.claim.sub',pg_temp.ne_id(1)::text,true);set local role authenticated;
insert into ne_ev values('legacy',pg_temp.ne_issue(pg_temp.ne_input(11)-'nonExpiring'));
insert into ne_ev values('finite',pg_temp.ne_issue((pg_temp.ne_input(12)-'nonExpiring')||jsonb_build_object('expiresAt',clock_timestamp()+interval '14 hours')));
insert into ne_ev values('all',pg_temp.ne_issue(pg_temp.ne_input(13))),('one',pg_temp.ne_issue(pg_temp.ne_input(14,array['space_1'])));
select ok((select v->'expiresAt'='null'::jsonb from ne_ev where k='all'),'explicit non-expiring reply returns JSON null');
select ok((select (v->>'expiresAt')::timestamptz between clock_timestamp()+interval '23 hours 59 minutes' and clock_timestamp()+interval '1 day' from ne_ev where k='legacy'),'legacy NULL expiry still defaults to one day');
select ok((select (v->>'expiresAt')::timestamptz between clock_timestamp()+interval '13 hours 59 minutes' and clock_timestamp()+interval '14 hours' from ne_ev where k='finite'),'existing finite expiry is preserved');
select is(pg_temp.ne_issue(pg_temp.ne_input(13))->'token','null'::jsonb,'same receipt never re-displays raw key');
select is(pg_temp.ne_issue(pg_temp.ne_input(13))-'token',(select v-'token' from ne_ev where k='all'),'replay retains exact indefinite metadata');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(13)-'nonExpiring')$q$,'23514','ai_agent_idempotency_conflict','old UUID cannot change expiry policy');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(20)-'expiresAt')$q$,'22023','ai_agent_invalid','unlimited intent requires explicit JSON null');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(20)||jsonb_build_object('expiresAt',clock_timestamp()+interval '1 day'))$q$,'22023','ai_agent_invalid','non-expiring mode cannot have finite expiry');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(20)||'{"nonExpiring":"true"}')$q$,'22023','ai_agent_invalid','expiry mode boolean is strict');
select throws_ok($q$select pg_temp.ne_issue((pg_temp.ne_input(20)-'nonExpiring')||jsonb_build_object('expiresAt',clock_timestamp()+interval '31 days'))$q$,'22023','ai_agent_invalid','finite limit remains 30 days');
select throws_ok($q$select pg_temp.ne_issue((pg_temp.ne_input(20)-'nonExpiring')||jsonb_build_object('expiresAt',clock_timestamp()-interval '1 second'))$q$,'22023','ai_agent_invalid','expired finite issuance rejected');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(20)||'{"scopes":["chat:send"]}')$q$,'22023','ai_agent_invalid','unlimited mode requires exact two scopes');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(20)||'{"scopes":["ai-agent:requests:read","chat:send","chat:outbox:read"]}')$q$,'22023','ai_agent_invalid','unlimited mode cannot gain employee request reads');
select throws_ok($q$select pg_temp.ne_issue(jsonb_set(pg_temp.ne_input(20),'{grant,purposes}','["ai_completion"]'))$q$,'22023','ai_agent_invalid','unlimited completion notifications rejected');
select throws_ok($q$select pg_temp.ne_issue(jsonb_set(pg_temp.ne_input(20),'{grant,queues}','["employee_requests"]'))$q$,'22023','ai_agent_invalid','unlimited Chat cannot gain employee queue grants');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(20,array['space_8']))$q$,'22023','ai_agent_invalid','arbitrary new rooms rejected');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('create',(pg_temp.ne_input(20)||jsonb_build_object('ownerProfileId',pg_temp.ne_id(2))))$q$,'22023','ai_agent_invalid','personal issuance does not accept new expiry mode');
reset role;
select ok((select expires_at is null from dashboard_private.ai_agent_credentials where id=(select (v->>'id')::uuid from ne_ev where k='all')),'credential expiry is SQL NULL');
select ok((select expires_at is null from dashboard_private.chat_credential_space_grants where credential_id=(select (v->>'id')::uuid from ne_ev where k='all')),'matching Chat grant expiry is SQL NULL');
select is((select expires_at::text from dashboard_private.ai_agent_credentials where id=(select (v->>'id')::uuid from ne_ev where k='finite')),(select ((v->>'expiresAt')::timestamptz)::text from ne_ev where k='finite'),'issuing indefinite keys does not change older finite key');
select ok(not exists(select 1 from dashboard_private.ai_agent_credential_grants where credential_id=(select (v->>'id')::uuid from ne_ev where k='all')),'no student/employee action grant is created');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_table_privilege(r,'dashboard_private.ai_agent_credentials','SELECT,INSERT,UPDATE,DELETE')),'private credential direct ACL remains closed');
select ok(not has_function_privilege('authenticated','public.create_ai_agent_credential_v1(text,text[],jsonb,timestamptz)','EXECUTE'),'legacy issuer cannot bypass receipt or expiry intent');
set local role service_role;
select is(pg_temp.ne_chat('chat_outbox',pg_temp.ne_message(n,'space_'||n))->>'created','true','explicit non-expiring grant supports room '||n) from generate_series(1,7)n;
select is(jsonb_array_length(pg_temp.ne_chat('list','{"limit":10}')->'items'),7,'non-expiring result read remains grant scoped');
select throws_ok($q$select pg_temp.ne_chat('chat_outbox',pg_temp.ne_message(20,'space_2'),'one')$q$,'42501','ai_agent_grant_forbidden','subset key cannot send to another configured room');
select throws_ok($q$select pg_temp.ne_chat('chat_outbox',pg_temp.ne_message(21,'space_1')||jsonb_build_object('bridgeSourceId',pg_temp.ne_id(91)))$q$,'42501','ai_agent_grant_forbidden','non-expiring key cannot impersonate a different source');
reset role;
update dashboard_private.ai_agent_credentials set expires_at=clock_timestamp()-interval '1 second' where id=(select (v->>'id')::uuid from ne_ev where k='finite');
set local role service_role;
select throws_ok($q$select pg_temp.ne_chat('list','{}','finite')$q$,'28000','ai_agent_unauthorized','expired finite credential is still denied');
reset role;
update dashboard_private.chat_credential_space_grants set revoked_at=clock_timestamp() where credential_id=(select (v->>'id')::uuid from ne_ev where k='one');
set local role service_role;
select throws_ok($q$select pg_temp.ne_chat('list','{}','one')$q$,'42501','ai_agent_grant_forbidden','revoked indefinite Chat grant is denied');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.ne_id(2)::text,true);set local role authenticated;
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(30))$q$,'42501','ai_agent_forbidden','non-admin cannot issue indefinite key');
reset role;select set_config('request.jwt.claim.sub',pg_temp.ne_id(1)::text,true);set local role authenticated;
select lives_ok($q$select public.ai_agent_credential_api_v1('revoke',jsonb_build_object('id',(select v->>'id' from ne_ev where k='all'),'idempotencyKey',pg_temp.ne_id(31)))$q$,'issuer can manually revoke indefinite key');
reset role;set local role service_role;
select throws_ok($q$select pg_temp.ne_chat('list','{}')$q$,'28000','ai_agent_unauthorized','manually revoked indefinite credential is denied');
reset role;
select ok((select revoked_at is not null from dashboard_private.chat_credential_space_grants where credential_id=(select (v->>'id')::uuid from ne_ev where k='all')),'manual revoke also revokes Chat grant');
select set_config('request.jwt.claim.sub',pg_temp.ne_id(3)::text,true);set local role authenticated;
do $$begin for n in 101..120 loop perform pg_temp.ne_issue(pg_temp.ne_input(n));end loop;end$$;
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(121))$q$,'54000','ai_agent_credential_limit','twenty indefinite keys exhaust the active-key limit');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(121)-'nonExpiring')$q$,'54000','ai_agent_credential_limit','indefinite keys count against finite central issuance too');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('create',jsonb_build_object('ownerProfileId',pg_temp.ne_id(2),'label','Synthetic personal','scopes',array['ai-agent:requests:read'],'grant',jsonb_build_object('queues',array['employee_requests'],'actions',array['read']),'idempotencyKey',pg_temp.ne_id(122)))$q$,'54000','ai_agent_credential_limit','shared personal issuer limit also counts indefinite central keys');
reset role;
-- Explicit mismatched NULL policy fails closed in the runtime verifier.
update dashboard_private.chat_credential_space_grants set expires_at=null where credential_id=(select (v->>'id')::uuid from ne_ev where k='legacy');
set local role service_role;
select throws_ok($q$select pg_temp.ne_chat('list','{}','legacy')$q$,'42501','ai_agent_grant_forbidden','finite credential cannot use NULL Chat grant');
reset role;
update dashboard_private.chat_credential_space_grants set expires_at=(select (v->>'expiresAt')::timestamptz from ne_ev where k='legacy') where credential_id=(select (v->>'id')::uuid from ne_ev where k='legacy');
-- Fail after NULL conversion but before receipt commit: no key/grant may survive.
select set_config('request.jwt.claim.sub',pg_temp.ne_id(1)::text,true);
create function pg_temp.ne_fail_receipt() returns trigger language plpgsql as $$begin if new.idempotency_key=pg_temp.ne_id(401) then raise exception using errcode='23514',message='synthetic_receipt_failure';end if;return new;end$$;
create trigger ne_receipt_failure before insert on dashboard_private.ai_agent_request_receipts for each row execute function pg_temp.ne_fail_receipt();
insert into ne_ev values('before_failure',jsonb_build_object('credentials',(select count(*) from dashboard_private.ai_agent_credentials),'grants',(select count(*) from dashboard_private.chat_credential_space_grants)));
set local role authenticated;
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(401))$q$,'23514','synthetic_receipt_failure','receipt failure rolls back converted key and grant');
reset role;
select is(jsonb_build_object('credentials',(select count(*) from dashboard_private.ai_agent_credentials),'grants',(select count(*) from dashboard_private.chat_credential_space_grants)),(select v from ne_ev where k='before_failure'),'failed issuance retains no newly generated key or grant');
drop trigger ne_receipt_failure on dashboard_private.ai_agent_request_receipts;
set local role authenticated;
insert into ne_ev values('ai_finite',public.ai_agent_credential_api_v1('create',jsonb_build_object('label','Finite AI regression','scopes',array['ai-agent:requests:read'],'grant',jsonb_build_object('queues',array['employee_requests'],'actions',array['read']),'idempotencyKey',pg_temp.ne_id(402))));
reset role;
select throws_ok($q$update dashboard_private.ai_agent_credentials set expires_at=null where id=(select (v->>'id')::uuid from ne_ev where k='ai_finite')$q$,'23514',null,'table constraint rejects NULL expiry on employee request key');
update dashboard_private.ai_agent_chat_support set issuance_enabled=false;
select set_config('request.jwt.claim.sub',pg_temp.ne_id(3)::text,true);
set local role authenticated;
select is(pg_temp.ne_issue(pg_temp.ne_input(101))->'token','null'::jsonb,'gate OFF still permits metadata-only receipt recovery');
select throws_ok($q$select pg_temp.ne_issue(pg_temp.ne_input(123))$q$,'42501','ai_agent_support_disabled','gate OFF blocks new unlimited issuance');
reset role;
select is((select count(*) from dashboard_private.chat_delivery_attempts where credential_id in(select id from dashboard_private.ai_agent_credentials where created_by in(pg_temp.ne_id(1),pg_temp.ne_id(3)))),0::bigint,'no provider attempt was started');
select * from finish();
rollback;
